# Search for Exchange Stabilization Fund related content
def search_json(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            search_json(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            search_json(v, f'{path}[{i}]')
    elif isinstance(obj, str):
        if 'exchange' in obj.lower() or 'stabilization' in obj.lower() or 'german' in obj.lower() or 'polish' in obj.lower() or 'zloty' in obj.lower():
            print(f'{path}: {obj[:200]}')

search_json(data)
